<script setup>
import {ref} from 'vue';import {Head,Link,router} from '@inertiajs/vue3';import axios from 'axios';import {message} from '../art';
defineProps({invitations:Object});const file=ref(null),preview=ref(null),links=ref([]),busy=ref(false),error=ref(''),copied=ref('');
async function upload(){busy.value=true;error.value='';preview.value=null;try{const body=new FormData();body.append('roster',file.value);preview.value=(await axios.post('/admin/onboarding/preview',body)).data}catch(e){error.value=message(e)}finally{busy.value=false}}
async function create(){await issue('/admin/onboarding/'+preview.value.id);if(!error.value)preview.value=null}
async function issue(url){busy.value=true;error.value='';try{links.value=(await axios.post(url)).data.links;router.reload({only:['invitations'],preserveScroll:true})}catch(e){error.value=message(e)}finally{busy.value=false}}
async function copy(link){try{await navigator.clipboard.writeText(link.url);copied.value=link.username}catch{error.value='Copy the visible link manually.'}}
function download(){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv=['username,cohort,invitation_url',...links.value.map(l=>[l.username,l.cohort,l.url].map(cell).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='sushi-invitations.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><Head title="Invite your cohort"/><h1>A seat for every learner</h1><p>Upload a CSV roster, check it, then create personal invitation links. Learners choose their own passwords.</p><Link href="/admin">← Head Chef</Link><p v-if="error" role="alert" class="notice error">{{error}}</p>
<section class="panel"><h2>1. Preview your roster</h2><p>Use <code>username,display_name,cohort</code> as the first row. Only username is required. Up to 500 learners per upload.</p><pre class="inset">username,display_name,cohort
sample-learner,Sample Learner,Clerks 2026</pre><label>Roster CSV<input type="file" accept=".csv,text/csv" @change="file=$event.target.files[0];preview=null"></label><button :disabled="!file||busy" @click="upload">Preview roster</button></section>
<section v-if="preview" class="panel"><h2>2. Check {{preview.rows.length}} learners</h2><ul v-if="preview.errors.length" class="error"><li v-for="e in preview.errors" :key="e">{{e}}</li></ul><div class="table-wrap"><table><thead><tr><th>Username</th><th>Display name</th><th>Cohort</th></tr></thead><tbody><tr v-for="(r,i) in preview.rows" :key="i"><td>{{r.username}}</td><td>{{r.display_name}}</td><td>{{r.cohort}}</td></tr></tbody></table></div><p>Existing accounts are preserved. Fix any errors and upload the CSV again.</p><button class="primary" :disabled="busy||!preview.id" @click="create">Create {{preview.rows.length}} learners and invitation links</button></section>
<section v-if="links.length" class="panel"><h2>3. Share invitations</h2><p>Each link can be used once and expires in seven days. Save these links now; only their fingerprints are retained by the app. No invitations have been sent automatically.</p><button @click="download">Download invitation list</button><div v-for="l in links" :key="l.username" class="inset"><strong>{{l.username}}</strong><label>Personal invitation<input :value="l.url" readonly @focus="$event.target.select()"></label><button @click="copy(l)">{{copied===l.username?'Copied':'Copy link'}}</button></div></section>
<section class="panel"><h2>Invitation history</h2><div v-for="i in invitations.data" :key="i.id" class="inset"><div class="row"><strong>{{i.username}} · {{i.cohort||'No cohort'}}</strong><span>{{i.accepted_at?'Accepted':i.revoked_at?'Revoked':Date.parse(i.expires_at+'Z')<Date.now()?'Expired':'Pending'}}</span></div><p>Expires {{i.expires_at}} UTC</p><div v-if="!i.accepted_at" class="row"><button :disabled="busy" @click="issue('/admin/onboarding/invitations/'+i.id+'/reissue')">Replace invitation link</button><button v-if="!i.revoked_at" :disabled="busy" @click="router.post('/admin/onboarding/invitations/'+i.id+'/revoke')">Revoke link</button></div></div><p v-if="!invitations.data.length">No invitations yet.</p><div class="row"><Link v-if="invitations.prev_page_url" :href="invitations.prev_page_url">Previous</Link><Link v-if="invitations.next_page_url" :href="invitations.next_page_url">Next</Link></div></section></template>
